using Essco.Domain.Treasury;namespace Essco.Tests.Unit.Treasury;
public sealed class DepositTests{[Fact]public void Validate_RejectsNonPositiveAmount()=>Assert.Contains((Valid()with{Amount=0}).Validate(),x=>x.Contains("monto",StringComparison.OrdinalIgnoreCase));[Fact]public void Validate_RejectsUnknownType()=>Assert.Contains((Valid()with{LiquidationType="OTRO"}).Validate(),x=>x.Contains("tipo",StringComparison.OrdinalIgnoreCase));[Fact]public void Validate_AcceptsValidDeposit()=>Assert.Empty(Valid().Validate());private static Deposit Valid()=>new(){Number="100",Date=new(2026,1,1),Bank="Banco",Amount=100,EmployeeCode="1",Notes="",LiquidationNumber="",LiquidationType="AGENTES",AccountingDate=new(2026,1,1)};}
